import React from 'react';

const WhyUs = () => {
    return (
        <section className="nh_whyUs">
            <div className="nh_container nh_whyInner">
                <h2>Your partner in safety, sustainability &amp; community</h2>
                <div className="nh_whyGrid">
                    <div className="nh_whyItem">
                        <svg viewBox="0 0 40 40" fill="none"><path d="M20 5 33 10v10c0 9.5-5.5 15-13 18-7.5-3-13-8.5-13-18V10z" stroke="#0c2340" strokeWidth="2" /><path d="M14 20l4 4 8-9" stroke="#0c2340" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" /></svg>
                        <h3>Professional Expertise</h3>
                    </div>
                    <div className="nh_whyItem">
                        <svg viewBox="0 0 40 40" fill="none"><path d="M9 22l6 6 4-4 4 4 8-8" stroke="#0c2340" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" /><path d="M9 15h4M27 15h4" stroke="#0c2340" strokeWidth="2" strokeLinecap="round" /></svg>
                        <h3>Reliable Service</h3>
                    </div>
                    <div className="nh_whyItem">
                        <svg viewBox="0 0 40 40" fill="none"><circle cx="20" cy="20" r="12" stroke="#0c2340" strokeWidth="2" /><path d="M20 8c3 4 3 20 0 24M12 12c4 3 12 3 16 0M12 28c4-3 12-3 16 0" stroke="#0c2340" strokeWidth="1.6" /></svg>
                        <h3>Sustainable Solutions</h3>
                    </div>
                </div>
            </div>
        </section>
    );
};

export default WhyUs;
